#!/usr/bin/env python3
"""Check outreach messages against the rules that decide whether they get read.

Input: a JSON file
    {"messages": [{"id": "acme-1", "lead": "Acme", "channel": "email",
                   "step": 1, "subject": "...", "body": "..."}]}
channel is one of: email, linkedin_note, linkedin, dm.

Output: JSON with one finding per broken rule. Exit code 1 when any finding
is an error, so a message that still has a placeholder in it cannot slip out.

    python3 lint_outreach.py messages.json
"""
import json
import re
import sys

SPAM = [
    "бесплатно", "гаранти", "срочно", "только сегодня", "скидк", "100%", "уникальн",
    "лучшее предложение", "без вложений", "заработ", "кликните", "нажмите здесь",
    "free", "guarantee", "act now", "limited time", "click here", "risk-free", "best price",
]
SELF_INTRO = re.compile(r"^\s*(меня зовут|я\s+—|я\s+-|my name is|i am |i'm )", re.I)
PLACEHOLDER = re.compile(r"\[[^\]\n]{1,60}\]|\{\{[^}\n]{1,60}\}\}")
LINK = re.compile(r"https?://|www\.", re.I)
WORD = re.compile(r"[\w'’-]+", re.U)


def words(text):
    return len(WORD.findall(text))


def first_line(text):
    for line in text.strip().splitlines():
        line = line.strip()
        # A greeting is not the first line that matters.
        if line and not re.match(r"^[\w\s]{0,25}[,!]?\s*(добрый день|здравствуйте|привет|hi|hello)?[.,!]?$", line, re.I):
            return line
    return ""


def check(message):
    found = []

    def add(level, rule, detail):
        found.append({"id": message.get("id", "?"), "level": level, "rule": rule, "detail": detail})

    channel = message.get("channel", "email")
    step = int(message.get("step", 1) or 1)
    body = message.get("body", "") or ""
    subject = message.get("subject", "") or ""
    count = words(body)

    if not body.strip():
        add("error", "empty", "Пустое сообщение.")
        return found

    for hit in PLACEHOLDER.findall(subject + "\n" + body):
        add("error", "placeholder", "Осталась незаполненная подстановка: %s" % hit)

    if channel == "email":
        if count > 120:
            add("error", "length", "%d слов. Холодное письмо длиннее 120 слов не дочитывают; цель — до 90." % count)
        elif count > 90:
            add("warning", "length", "%d слов. Цель — до 90." % count)
        if not subject.strip():
            add("error", "subject", "Нет темы письма.")
        elif len(subject) > 45:
            add("warning", "subject", "Тема %d знаков. В списке писем видно около 45." % len(subject))
        if subject and subject.upper() == subject and re.search(r"[A-Za-zА-Яа-я]{4,}", subject):
            add("warning", "subject", "Тема целиком заглавными буквами.")
        if step == 1 and LINK.search(body):
            add("error", "link", "Ссылка в первом письме: такие чаще уходят в спам.")
    elif channel == "linkedin_note":
        if len(body) > 300:
            add("error", "length", "%d знаков. Заявка в контакты LinkedIn вмещает 300." % len(body))
    elif channel in ("dm", "linkedin"):
        if step == 1 and (len(body) > 350 or body.strip().count("\n") > 3):
            add("warning", "length", "Первое сообщение в мессенджере длиннее трёх строк.")
        if step == 1 and LINK.search(body):
            add("warning", "link", "Ссылка в первом сообщении незнакомому человеку.")

    questions = body.count("?")
    if questions > 1:
        add("warning", "questions", "%d вопроса. Одно сообщение — один вопрос." % questions)
    if questions == 0 and channel != "linkedin_note":
        add("warning", "questions", "Нет вопроса: получателю не на что ответить.")

    if body.count("!") > 1:
        add("warning", "tone", "Восклицательных знаков: %d." % body.count("!"))

    lowered = (subject + " " + body).lower()
    for term in SPAM:
        if term in lowered:
            add("warning", "spam_word", "Слово-триггер спам-фильтров: «%s»." % term)

    if step == 1 and SELF_INTRO.match(first_line(body) or body):
        add("warning", "first_line", "Первая строка — о себе. Начните с факта о получателе.")

    return found


def main():
    if len(sys.argv) != 2 or sys.argv[1] in ("-h", "--help"):
        print(__doc__)
        return 2
    with open(sys.argv[1], encoding="utf-8") as handle:
        data = json.load(handle)
    messages = data["messages"] if isinstance(data, dict) else data

    findings = []
    openers = {}
    for message in messages:
        findings.extend(check(message))
        if int(message.get("step", 1) or 1) == 1:
            opener = first_line(message.get("body", "")).lower()
            if opener:
                openers.setdefault(opener, []).append(message.get("id", "?"))

    for opener, ids in openers.items():
        leads = {m.get("lead") for m in messages if m.get("id") in ids}
        if len(ids) > 1 and len(leads) > 1:
            findings.append({
                "id": ", ".join(ids), "level": "warning", "rule": "not_personal",
                "detail": "Одинаковая первая строка у разных получателей: «%s»." % opener[:80],
            })

    errors = sum(1 for f in findings if f["level"] == "error")
    report = {
        "summary": {"messages": len(messages), "errors": errors, "warnings": len(findings) - errors},
        "findings": findings,
    }
    print(json.dumps(report, ensure_ascii=False, indent=1))
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Tools that keep repurposed content honest to its source video.

    python3 transcript_tools.py parse talk.srt
        SRT, VTT or plain lines like "[00:01:23] text" -> JSON segments.

    python3 transcript_tools.py verify talk.srt posts.md email.md article.md
        Every quotation in the drafts must exist in the transcript. Reports
        each quote as exact, close (wording drifted) or missing (invented).
        Also lists numbers in the drafts that the transcript never mentions.

    python3 transcript_tools.py clips talk.srt clips.json
        clips.json: [{"start": "00:01:10", "end": "00:01:42", "title": "..."}]
        Checks each clip is 20-45 seconds, inside the video, and prints the
        words actually spoken in that window.
"""
import difflib
import json
import re
import sys

STAMP = r"(?:(\d{1,2}):)?(\d{1,2}):(\d{2})(?:[.,](\d{1,3}))?"
CUE = re.compile(STAMP + r"\s*-->\s*" + STAMP)
LINE = re.compile(r"^\s*\[?" + STAMP + r"\]?\s*[-–—:]?\s*(.+)$")
QUOTE = re.compile(r"«([^»]{12,})»|“([^”]{12,})”|\"([^\"\n]{12,})\"")
NUMBER = re.compile(r"(?<![\w.])\d[\d  .,]*\d|\d")


def seconds(h, m, s, ms=None):
    return int(h or 0) * 3600 + int(m) * 60 + int(s) + (int((ms or "0").ljust(3, "0")[:3]) / 1000.0)


def stamp(value):
    value = int(value)
    return "%02d:%02d:%02d" % (value // 3600, value % 3600 // 60, value % 60)


def to_seconds(text):
    match = re.match(r"^\s*" + STAMP + r"\s*$", str(text))
    if not match:
        raise SystemExit("Не понял таймкод: %r" % text)
    return seconds(*match.groups())


def parse(path):
    raw = open(path, encoding="utf-8-sig").read().replace("\r\n", "\n")
    segments = []
    if "-->" in raw:
        for block in re.split(r"\n\s*\n", raw):
            lines = [line for line in block.strip().splitlines() if line.strip()]
            for index, line in enumerate(lines):
                cue = CUE.search(line)
                if cue:
                    groups = cue.groups()
                    text = " ".join(lines[index + 1:])
                    text = re.sub(r"<[^>]+>", "", text).strip()
                    if text:
                        segments.append({"start": seconds(*groups[:4]), "end": seconds(*groups[4:]), "text": text})
                    break
    else:
        for line in raw.splitlines():
            match = LINE.match(line)
            if match:
                segments.append({"start": seconds(*match.groups()[:4]), "end": None, "text": match.group(5).strip()})
            elif line.strip() and segments:
                segments[-1]["text"] += " " + line.strip()
            elif line.strip():
                segments.append({"start": 0.0, "end": None, "text": line.strip()})
        for current, following in zip(segments, segments[1:]):
            current["end"] = following["start"]
        if segments and segments[-1]["end"] is None:
            segments[-1]["end"] = segments[-1]["start"] + max(2.0, len(segments[-1]["text"].split()) / 2.5)
    return segments


def normalise(text):
    text = text.lower().replace("ё", "е")
    text = re.sub(r"[^\w\s]", " ", text, flags=re.U)
    return re.sub(r"\s+", " ", text).strip()


def best_match(needle, haystack_words):
    """Closest window of the transcript to a quote, by word-level similarity."""
    target = needle.split()
    size = len(target)
    best, where = 0.0, 0
    step = max(1, size // 4)
    for start in range(0, max(1, len(haystack_words) - size + 1), step):
        ratio = difflib.SequenceMatcher(None, target, haystack_words[start:start + size]).ratio()
        if ratio > best:
            best, where = ratio, start
    for start in range(max(0, where - step), min(len(haystack_words), where + step + 1)):
        ratio = difflib.SequenceMatcher(None, target, haystack_words[start:start + size]).ratio()
        if ratio > best:
            best, where = ratio, start
    return best, " ".join(haystack_words[where:where + size])


def digits(text):
    found = set()
    for hit in NUMBER.findall(text):
        clean = re.sub(r"[\s  ]", "", hit).rstrip(".,")
        # Single digits are everywhere ("3 шага") and prove nothing either way.
        if len(clean) >= 2:
            found.add(clean.replace(",", "."))
    return found


def verify(transcript_path, draft_paths):
    segments = parse(transcript_path)
    source = normalise(" ".join(s["text"] for s in segments))
    source_words = source.split()
    source_numbers = digits(" ".join(s["text"] for s in segments))
    report = {"quotes": [], "numbers_not_in_transcript": [], "summary": {}}
    for path in draft_paths:
        text = open(path, encoding="utf-8").read()
        quotes = [next(g for g in match if g) for match in QUOTE.findall(text)]
        quotes += [line.lstrip("> ").strip() for line in text.splitlines() if line.startswith(">") and len(line) > 14]
        for quote in quotes:
            needle = normalise(quote)
            if len(needle.split()) < 4:
                continue
            if needle in source:
                status, ratio, nearest = "exact", 1.0, None
            else:
                ratio, nearest = best_match(needle, source_words)
                status = "close" if ratio >= 0.6 else "missing"
            entry = {"file": path, "quote": quote, "status": status, "similarity": round(ratio, 2)}
            if nearest and status != "exact":
                entry["nearest_in_transcript"] = nearest
            report["quotes"].append(entry)
        for number in sorted(digits(text) - source_numbers):
            report["numbers_not_in_transcript"].append({"file": path, "number": number})
    counts = {"exact": 0, "close": 0, "missing": 0}
    for entry in report["quotes"]:
        counts[entry["status"]] += 1
    report["summary"] = dict(counts, numbers_to_check=len(report["numbers_not_in_transcript"]))
    report["how_to_read"] = (
        "missing — цитаты нет в расшифровке, удалите или замените. close — формулировка изменена, "
        "верните дословную. numbers_not_in_transcript — число не встречается цифрами; "
        "проверьте вручную, возможно, в расшифровке оно записано словами."
    )
    return report, 1 if counts["missing"] else 0


def clips(transcript_path, clips_path):
    segments = parse(transcript_path)
    total = max((s["end"] or s["start"]) for s in segments) if segments else 0
    result = []
    failed = False
    for clip in json.load(open(clips_path, encoding="utf-8")):
        start, end = to_seconds(clip["start"]), to_seconds(clip["end"])
        length = end - start
        problems = []
        if length < 20:
            problems.append("короче 20 секунд")
        if length > 45:
            problems.append("длиннее 45 секунд")
        if start < 0 or end > total + 1:
            problems.append("выходит за пределы видео (%s)" % stamp(total))
        spoken = " ".join(s["text"] for s in segments if s["start"] < end and (s["end"] or s["start"]) > start)
        if not spoken:
            problems.append("в этом отрезке нет речи")
        failed = failed or bool(problems)
        result.append({
            "title": clip.get("title", ""), "start": stamp(start), "end": stamp(end),
            "seconds": round(length, 1), "words": len(spoken.split()), "problems": problems, "spoken": spoken,
        })
    return {"video_length": stamp(total), "clips": result}, 1 if failed else 0


def main():
    args = sys.argv[1:]
    if len(args) < 2 or args[0] not in ("parse", "verify", "clips"):
        print(__doc__)
        return 2
    code = 0
    if args[0] == "parse":
        segments = parse(args[1])
        words = sum(len(s["text"].split()) for s in segments)
        length = max((s["end"] or s["start"]) for s in segments) if segments else 0
        out = {
            "summary": {"segments": len(segments), "words": words, "length": stamp(length)},
            "segments": [{"start": stamp(s["start"]), "end": stamp(s["end"] or s["start"]), "text": s["text"]} for s in segments],
        }
    elif args[0] == "verify":
        if len(args) < 3:
            raise SystemExit("verify: укажите расшифровку и хотя бы один черновик")
        out, code = verify(args[1], args[2:])
    else:
        if len(args) != 3:
            raise SystemExit("clips: укажите расшифровку и clips.json")
        out, code = clips(args[1], args[2])
    print(json.dumps(out, ensure_ascii=False, indent=1))
    return code


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Find the problems in an exported n8n workflow that break it in production.

    python3 n8n_lint.py workflow.json

Reads the JSON that n8n produces with "Download" or "Copy to clipboard".
Reports findings with a severity: critical, high, medium, low, info.
Secrets are masked in the output. Exit code 1 when anything is critical or
high. Standard library only.
"""
import json
import re
import sys

SECRET_PATTERNS = [
    ("OpenAI-style key", re.compile(r"\bsk-[A-Za-z0-9_-]{20,}")),
    ("Anthropic key", re.compile(r"\bsk-ant-[A-Za-z0-9_-]{20,}")),
    ("Bearer token", re.compile(r"\bBearer\s+[A-Za-z0-9._~+/-]{20,}=*")),
    ("Slack token", re.compile(r"\bxox[abpors]-[A-Za-z0-9-]{10,}")),
    ("Google API key", re.compile(r"\bAIza[0-9A-Za-z_-]{35}")),
    ("GitHub token", re.compile(r"\bgh[pousr]_[A-Za-z0-9]{30,}")),
    ("Telegram bot token", re.compile(r"\b\d{8,10}:[A-Za-z0-9_-]{35}\b")),
    ("Stripe key", re.compile(r"\b[sr]k_(?:live|test)_[A-Za-z0-9]{20,}")),
    ("AWS access key", re.compile(r"\bAKIA[0-9A-Z]{16}\b")),
    ("Private key", re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----")),
]
SECRET_NAME = re.compile(r"(api[_-]?key|apikey|token|secret|password|passwd|authorization|access[_-]?key)", re.I)
DEFAULT_NAME = re.compile(
    r"^(HTTP Request|Code|Set|Edit Fields|If|Switch|Merge|Webhook|Function|Function Item|Wait|"
    r"Respond to Webhook|AI Agent|Basic LLM Chain|OpenAI|Gmail|Google Sheets|Telegram|Slack|"
    r"Schedule Trigger|Filter|Loop Over Items|Split Out|Aggregate|Execute Workflow)\d*$"
)
TRIGGER = re.compile(r"trigger|webhook$|\.cron$|\.start$|formTrigger|chatTrigger", re.I)
ORDER = ["critical", "high", "medium", "low", "info"]


def mask(value):
    value = str(value)
    return value[:6] + "…" + value[-2:] if len(value) > 12 else "…"


def strings(node, path=""):
    if isinstance(node, dict):
        for key, value in node.items():
            for item in strings(value, "%s.%s" % (path, key) if path else key):
                yield item
    elif isinstance(node, list):
        for index, value in enumerate(node):
            for item in strings(value, "%s[%d]" % (path, index)):
                yield item
    elif isinstance(node, str):
        yield path, node


def is_expression(value):
    return value.startswith("=") or "{{" in value or "$env" in value or "$credentials" in value or "$secrets" in value


def main():
    if len(sys.argv) != 2 or sys.argv[1] in ("-h", "--help"):
        print(__doc__)
        return 2
    data = json.load(open(sys.argv[1], encoding="utf-8"))
    if isinstance(data, list):
        data = data[0]
    nodes = data.get("nodes") or []
    connections = data.get("connections") or {}
    settings = data.get("settings") or {}
    findings = []

    def add(severity, rule, node, detail, fix):
        findings.append({"severity": severity, "rule": rule, "node": node, "detail": detail, "fix": fix})

    if not nodes:
        raise SystemExit("В файле нет узлов: это не экспорт воркфлоу n8n.")

    incoming, outgoing = set(), set()
    for source, outputs in connections.items():
        for branches in outputs.values():
            for branch in branches or []:
                for link in branch or []:
                    outgoing.add(source)
                    incoming.add(link.get("node"))

    has_error_trigger = any("errorTrigger" in (n.get("type") or "") for n in nodes)
    sticky = [n for n in nodes if "stickyNote" in (n.get("type") or "")]
    work_nodes = [n for n in nodes if n not in sticky]

    for node in work_nodes:
        name, kind = node.get("name", "?"), node.get("type", "")
        params = node.get("parameters") or {}

        for path, value in strings(params):
            for label, pattern in SECRET_PATTERNS:
                hit = pattern.search(value)
                if hit:
                    add("critical", "secret_in_node", name,
                        "%s в параметре `%s`: %s" % (label, path, mask(hit.group(0))),
                        "Перенесите в учётные данные n8n (Credentials) и перевыпустите ключ: он уже попал в экспорт.")
                    break
            else:
                leaf = re.split(r"[.\[]", path)[-1] if path else ""
                if SECRET_NAME.search(leaf) and len(value) >= 12 and not is_expression(value) and " " not in value:
                    add("high", "possible_secret", name,
                        "Параметр `%s` похож на секрет, записанный текстом: %s" % (path, mask(value)),
                        "Проверьте. Если это ключ — перенесите в Credentials и перевыпустите.")

        if kind.endswith(".webhook") or kind.endswith("formTrigger"):
            if (params.get("authentication") or "none") == "none":
                add("high", "webhook_without_auth", name,
                    "Webhook принимает запросы от кого угодно.",
                    "Включите Header Auth или проверку подписи; адрес вебхука не является секретом.")
            if params.get("responseMode") in (None, "onReceived"):
                add("info", "webhook_responds_immediately", name,
                    "Отвечает сразу, не дожидаясь результата.",
                    "Если вызывающей системе нужен результат — режим «Using Respond to Webhook node».")

        calls_out = kind.endswith(".httpRequest") or bool(node.get("credentials"))
        if calls_out and not TRIGGER.search(kind):
            if not node.get("retryOnFail"):
                add("medium", "no_retry", name,
                    "Обращается к внешней системе без повторов при сбое.",
                    "Settings → Retry On Fail: 3 попытки с паузой 2–5 секунд.")
            on_error = node.get("onError") or ("continueRegularOutput" if node.get("continueOnFail") else "stopWorkflow")
            if on_error == "continueRegularOutput":
                add("medium", "error_swallowed", name,
                    "При ошибке продолжает работу как ни в чём не бывало: сбой никто не увидит.",
                    "On Error → Continue (using error output) и ветка, которая сообщает о сбое.")
        if kind.endswith(".httpRequest"):
            options = params.get("options") or {}
            if "timeout" not in options:
                add("low", "no_timeout", name, "Не задан таймаут запроса.", "Options → Timeout, например 15000 мс.")
            url = str(params.get("url", ""))
            if url.startswith("http://") and "localhost" not in url and "127.0.0.1" not in url:
                add("medium", "plain_http", name, "Запрос по незашифрованному http.", "Используйте https.")

        if kind.endswith(".code") or kind.endswith(".function"):
            code = str(params.get("jsCode") or params.get("functionCode") or params.get("pythonCode") or "")
            for needle, why in (("process.env", "читает переменные окружения сервера"),
                                ("child_process", "запускает команды на сервере"),
                                ("eval(", "выполняет строку как код")):
                if needle in code:
                    add("medium", "risky_code", name, "Code-узел %s (`%s`)." % (why, needle),
                        "Убедитесь, что это необходимо и входные данные не приходят извне.")

        if DEFAULT_NAME.match(name):
            add("low", "default_name", name, "Имя узла по умолчанию.",
                "Назовите по действию: «Создать сделку в CRM», а не «HTTP Request1».")
        if node.get("disabled"):
            add("info", "disabled_node", name, "Узел выключен.", "Удалите или опишите в заметке, зачем он оставлен.")
        if not TRIGGER.search(kind) and name not in incoming and name not in outgoing:
            add("low", "disconnected", name, "Узел ни с чем не соединён.", "Удалите или подключите.")

    agents = [n for n in work_nodes if "langchain.agent" in (n.get("type") or "")]
    tools = [n for n in work_nodes if re.search(r"langchain\.tool|Tool$", n.get("type") or "")]
    if agents and tools:
        add("info", "agent_with_tools", agents[0].get("name", "?"),
            "AI-агент с %d инструментами. Если он читает письма, сайты или документы, в них могут быть чужие инструкции." % len(tools),
            "Оставьте агенту только нужные инструменты; действия с деньгами, удалением и отправкой наружу — через подтверждение человеком.")

    triggers = [n for n in work_nodes if TRIGGER.search(n.get("type") or "")]
    if not triggers:
        add("info", "no_trigger", "-", "В воркфлоу нет триггера.", "Нормально для подворкфлоу; иначе добавьте триггер.")
    if not settings.get("errorWorkflow") and not has_error_trigger:
        add("medium", "no_error_workflow", "-",
            "Не назначен воркфлоу для ошибок: о падении вы узнаете от клиента.",
            "Settings → Error Workflow: отдельный воркфлоу с Error Trigger, который пишет в Telegram или почту.")
    if data.get("pinData"):
        add("medium", "pinned_data", "-",
            "В экспорте остались закреплённые тестовые данные (%d узлов). В них могут быть данные клиентов." % len(data["pinData"]),
            "Открепите данные перед экспортом и передачей файла.")
    if not sticky and not any(n.get("notes") for n in work_nodes):
        add("low", "no_documentation", "-", "Нет ни одной заметки.",
            "Добавьте заметку в начале: что делает воркфлоу, кто владелец, дата.")
    if settings.get("saveDataSuccessExecution") == "all" and any("personal" in json.dumps(n, ensure_ascii=False).lower() for n in work_nodes):
        add("info", "execution_data", "-", "Сохраняются данные всех успешных запусков.",
            "Если в них персональные данные — ограничьте срок хранения.")

    findings.sort(key=lambda f: ORDER.index(f["severity"]))
    counts = {level: sum(1 for f in findings if f["severity"] == level) for level in ORDER}
    credentials = sorted({key for n in work_nodes for key in (n.get("credentials") or {})})
    print(json.dumps({
        "workflow": data.get("name", ""),
        "nodes": len(work_nodes),
        "triggers": [n.get("name") for n in triggers],
        "credential_types": credentials,
        "has_error_handling": bool(settings.get("errorWorkflow") or has_error_trigger),
        "counts": counts,
        "findings": findings,
    }, ensure_ascii=False, indent=1))
    return 1 if counts["critical"] or counts["high"] else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Collect the facts an SEO and AI-search audit needs from one page.

    python3 page_audit.py https://example.com/services/
    python3 page_audit.py saved-page.html          # a local file, no network

For a URL it also reads /robots.txt (rules for AI crawlers and the sitemap
line) and checks whether /llms.txt exists. It reports facts only; judging
them is the skill's job. Uses the Python standard library, nothing to install.
"""
import json
import re
import sys
import urllib.error
import urllib.parse
import urllib.request
from html.parser import HTMLParser

AGENT = "Mozilla/5.0 (compatible; page-audit/1.0)"
AI_BOTS = ["GPTBot", "OAI-SearchBot", "ChatGPT-User", "ClaudeBot", "Claude-SearchBot", "PerplexityBot", "Google-Extended", "Bingbot", "CCBot"]
SKIP = {"script", "style", "noscript", "template", "svg"}


class Page(HTMLParser):
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.title = ""
        self.meta = {}
        self.links = []
        self.headings = []
        self.images = []
        self.jsonld = []
        self.canonical = None
        self.lang = None
        self.hreflang = []
        self.text = []
        self._stack = []
        self._capture = None
        self._buffer = []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "br":
            # A line break separates words even when the markup has no space.
            self.handle_data(" ")
            return
        self._stack.append(tag)
        if tag == "html":
            self.lang = a.get("lang")
        elif tag == "meta":
            key = (a.get("name") or a.get("property") or "").lower()
            if key:
                self.meta[key] = a.get("content", "")
        elif tag == "link":
            rel = (a.get("rel") or "").lower()
            if "canonical" in rel:
                self.canonical = a.get("href")
            if "alternate" in rel and a.get("hreflang"):
                self.hreflang.append(a.get("hreflang"))
        elif tag == "a" and a.get("href"):
            self.links.append(a["href"])
        elif tag == "img":
            self.images.append({"src": a.get("src", ""), "alt": a.get("alt")})
        if tag == "title" or re.fullmatch(r"h[1-6]", tag):
            self._capture, self._buffer = tag, []
        if tag == "script" and (a.get("type") or "").lower() == "application/ld+json":
            self._capture, self._buffer = "jsonld", []

    def handle_endtag(self, tag):
        if self._capture and (tag == self._capture or (self._capture == "jsonld" and tag == "script")):
            content = " ".join("".join(self._buffer).split())
            if self._capture == "title":
                self.title = self.title or content
            elif self._capture == "jsonld":
                self.jsonld.append("".join(self._buffer))
            else:
                self.headings.append({"level": int(self._capture[1]), "text": content})
            self._capture = None
        while self._stack and self._stack.pop() != tag:
            pass

    def handle_data(self, data):
        if self._capture:
            self._buffer.append(data)
        if not SKIP.intersection(self._stack):
            self.text.append(data)


def fetch(url, limit=3_000_000):
    request = urllib.request.Request(url, headers={"User-Agent": AGENT, "Accept": "text/html,*/*"})
    with urllib.request.urlopen(request, timeout=20) as response:
        raw = response.read(limit)
        charset = response.headers.get_content_charset() or "utf-8"
        return response.status, response.geturl(), dict(response.headers), raw.decode(charset, "replace")


def schema_types(blocks):
    types, broken = [], 0

    def walk(node):
        if isinstance(node, dict):
            kind = node.get("@type")
            if isinstance(kind, str):
                types.append(kind)
            elif isinstance(kind, list):
                types.extend(str(k) for k in kind)
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for value in node:
                walk(value)

    for block in blocks:
        try:
            walk(json.loads(block))
        except ValueError:
            broken += 1
    return sorted(set(types)), broken


def robots_report(origin):
    report = {"found": False, "sitemaps": [], "ai_bots": {}}
    try:
        _, _, _, body = fetch(origin + "/robots.txt", 300_000)
    except (urllib.error.URLError, OSError, ValueError):
        return report
    report["found"] = True
    groups, agents, fresh = {}, [], True
    for line in body.splitlines():
        line = line.split("#", 1)[0].strip()
        if ":" not in line:
            continue
        key, value = [part.strip() for part in line.split(":", 1)]
        key = key.lower()
        if key == "sitemap":
            report["sitemaps"].append(value)
        elif key == "user-agent":
            if not fresh:
                agents, fresh = [], True
            agents.append(value.lower())
            groups.setdefault(value.lower(), [])
        elif key in ("allow", "disallow"):
            fresh = False
            for agent in agents:
                groups[agent].append((key, value))
    for bot in AI_BOTS:
        rules = groups.get(bot.lower())
        source = bot if rules is not None else "*"
        rules = rules if rules is not None else groups.get("*", [])
        blocked = any(kind == "disallow" and value == "/" for kind, value in rules)
        report["ai_bots"][bot] = {"rule_from": source, "blocked_sitewide": blocked}
    return report


def exists(url):
    try:
        status, final, headers, body = fetch(url, 20_000)
        return status == 200 and "<html" not in body[:500].lower()
    except (urllib.error.URLError, OSError, ValueError):
        return False


def main():
    if len(sys.argv) != 2 or sys.argv[1] in ("-h", "--help"):
        print(__doc__)
        return 2
    target = sys.argv[1]
    remote = re.match(r"^https?://", target) is not None
    out = {"target": target}

    if remote:
        try:
            status, final, headers, html = fetch(target)
        except urllib.error.HTTPError as error:
            print(json.dumps({"target": target, "error": "HTTP %s" % error.code}, ensure_ascii=False))
            return 1
        except (urllib.error.URLError, OSError) as error:
            print(json.dumps({"target": target, "error": str(error)}, ensure_ascii=False))
            return 1
        out.update(status=status, final_url=final, redirected=final.rstrip("/") != target.rstrip("/"))
        out["x_robots_tag"] = headers.get("X-Robots-Tag") or headers.get("x-robots-tag")
    else:
        html = open(target, encoding="utf-8", errors="replace").read()

    page = Page()
    page.feed(html)
    text = " ".join(" ".join(page.text).split())
    words = re.findall(r"[\w'’-]+", text, flags=re.U)
    description = page.meta.get("description", "")
    h1 = [h["text"] for h in page.headings if h["level"] == 1]
    types, broken = schema_types(page.jsonld)

    levels = [h["level"] for h in page.headings]
    skipped = [
        "%s → h%d" % ("h%d" % a, b) for a, b in zip(levels, levels[1:]) if b - a > 1
    ]
    question_headings = [h["text"] for h in page.headings if h["text"].endswith("?")]

    host = urllib.parse.urlparse(out.get("final_url", target)).netloc if remote else ""
    internal = external = 0
    for href in page.links:
        parsed = urllib.parse.urlparse(href)
        if parsed.scheme in ("mailto", "tel", "javascript"):
            continue
        if parsed.netloc and parsed.netloc != host:
            external += 1
        else:
            internal += 1

    out.update({
        "html_bytes": len(html.encode("utf-8")),
        "lang": page.lang,
        "title": {"text": page.title, "length": len(page.title)},
        "meta_description": {"text": description, "length": len(description)},
        "meta_robots": page.meta.get("robots"),
        "canonical": page.canonical,
        "hreflang": page.hreflang,
        "h1": h1,
        "headings": page.headings[:60],
        "heading_levels_skipped": skipped,
        "question_headings": question_headings,
        "words": len(words),
        "first_200_chars": text[:200],
        "images": {
            "total": len(page.images),
            "without_alt": sum(1 for image in page.images if image["alt"] is None),
            "empty_alt": sum(1 for image in page.images if image["alt"] == ""),
        },
        "links": {"internal": internal, "external": external},
        "open_graph": {key: value for key, value in page.meta.items() if key.startswith("og:")},
        "twitter_card": page.meta.get("twitter:card"),
        "structured_data": {"types": types, "blocks": len(page.jsonld), "invalid_blocks": broken},
        "viewport": page.meta.get("viewport"),
    })

    # A page that is nearly empty before scripts run is invisible to crawlers
    # that do not execute JavaScript, which includes most AI crawlers.
    out["rendering"] = {
        "words_in_raw_html": len(words),
        "likely_client_rendered": len(words) < 120 and html.count("<script") > 5,
    }

    if remote:
        parsed = urllib.parse.urlparse(out["final_url"])
        origin = "%s://%s" % (parsed.scheme, parsed.netloc)
        out["robots_txt"] = robots_report(origin)
        out["llms_txt"] = exists(origin + "/llms.txt")
        if not out["robots_txt"]["sitemaps"]:
            out["sitemap_xml_at_default_path"] = exists(origin + "/sitemap.xml")

    print(json.dumps(out, ensure_ascii=False, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Turn a table of this period against last period into deltas a report can cite.

CSV columns (header row required; extra columns are ignored):
    metric, previous, current, target (optional), direction (optional), unit (optional)
direction is "up" when higher is better (default) or "down" when lower is
better, for example response time or cost per lead.

    python3 metrics_delta.py metrics.csv
    python3 metrics_delta.py metrics.csv --format md

Numbers may use a comma or a point as the decimal mark and spaces as
thousands separators. Rows that cannot be read are reported, not dropped.
"""
import argparse
import csv
import json
import re
import sys

ALIASES = {
    "metric": ["metric", "метрика", "показатель", "name"],
    "previous": ["previous", "prev", "было", "прошлый", "прошлая", "last"],
    "current": ["current", "now", "стало", "текущий", "текущая", "this"],
    "target": ["target", "цель", "план", "goal"],
    "direction": ["direction", "направление"],
    "unit": ["unit", "единица", "ед"],
}


def number(raw):
    if raw is None:
        return None
    text = re.sub(r"[\s  %€$₽₴]", "", str(raw))
    if not text:
        return None
    if "," in text and "." in text:
        text = text.replace(",", "") if text.rfind(".") > text.rfind(",") else text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", ".")
    try:
        return float(text)
    except ValueError:
        return None


def column(header, field):
    lowered = [h.strip().lower() for h in header]
    for alias in ALIASES[field]:
        for index, name in enumerate(lowered):
            if name == alias or name.startswith(alias):
                return index
    return None


def fmt(value):
    if value is None:
        return "—"
    if abs(value - round(value)) < 1e-9:
        return "{:,}".format(int(round(value))).replace(",", " ")
    return ("%.2f" % value).rstrip("0").rstrip(".")


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("file")
    parser.add_argument("--format", choices=["json", "md"], default="json")
    args = parser.parse_args()

    with open(args.file, encoding="utf-8-sig", newline="") as handle:
        sample = handle.read(4096)
        handle.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t")
        except csv.Error:
            dialect = csv.excel
        rows = list(csv.reader(handle, dialect))
    if len(rows) < 2:
        raise SystemExit("В файле нет строк с данными.")

    header = rows[0]
    index = {field: column(header, field) for field in ALIASES}
    missing = [field for field in ("metric", "previous", "current") if index[field] is None]
    if missing:
        raise SystemExit("Не нашёл колонки: %s. Есть: %s" % (", ".join(missing), ", ".join(header)))

    def cell(row, field):
        position = index[field]
        return row[position].strip() if position is not None and position < len(row) else ""

    metrics, unreadable = [], []
    for line, row in enumerate(rows[1:], start=2):
        if not any(part.strip() for part in row):
            continue
        name = cell(row, "metric")
        previous, current = number(cell(row, "previous")), number(cell(row, "current"))
        if not name or current is None:
            unreadable.append({"line": line, "row": row})
            continue
        down = cell(row, "direction").lower() in ("down", "вниз", "меньше", "lower")
        target = number(cell(row, "target"))
        delta = None if previous is None else current - previous
        percent = None if previous in (None, 0) else delta / abs(previous) * 100
        if delta is None or delta == 0:
            trend = "без изменений" if delta == 0 else "нет базы для сравнения"
        else:
            trend = "лучше" if (delta < 0) == down else "хуже"
        on_target = None
        if target is not None:
            on_target = current <= target if down else current >= target
        metrics.append({
            "metric": name, "unit": cell(row, "unit"), "previous": previous, "current": current,
            "delta": None if delta is None else round(delta, 4),
            "delta_percent": None if percent is None else round(percent, 1),
            "trend": trend, "target": target, "on_target": on_target,
            "lower_is_better": down,
        })

    moved = [m for m in metrics if m["delta_percent"] is not None]
    better = sorted([m for m in moved if m["trend"] == "лучше"], key=lambda m: -abs(m["delta_percent"]))
    worse = sorted([m for m in moved if m["trend"] == "хуже"], key=lambda m: -abs(m["delta_percent"]))
    off_target = [m["metric"] for m in metrics if m["on_target"] is False]

    if args.format == "md":
        print("| Показатель | Было | Стало | Изменение | Цель | Статус |")
        print("|---|---|---|---|---|---|")
        for m in metrics:
            change = "—" if m["delta_percent"] is None else "%+.1f%%" % m["delta_percent"]
            status = m["trend"]
            if m["on_target"] is not None:
                status += ", цель %s" % ("выполнена" if m["on_target"] else "не выполнена")
            unit = " " + m["unit"] if m["unit"] else ""
            print("| %s | %s%s | %s%s | %s | %s | %s |" % (
                m["metric"], fmt(m["previous"]), unit, fmt(m["current"]), unit, change, fmt(m["target"]), status))
        return 0

    print(json.dumps({
        "metrics": metrics,
        "biggest_improvements": [m["metric"] for m in better[:3]],
        "biggest_declines": [m["metric"] for m in worse[:3]],
        "off_target": off_target,
        "unreadable_rows": unreadable,
        "note": "Процент не считается, когда прошлое значение равно нулю или отсутствует.",
    }, ensure_ascii=False, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(main())
